exercises.solution:
cat > ~/bin/cert-wygasa.sh <<'EOF'
#!/bin/bash
d=${1:?podaj domene}
koniec=$(echo | openssl s_client -connect "$d:443" -servername "$d" 2>/dev/null | openssl x509 -noout -enddate | cut -d= -f2)
dni=$(( ( $(date -d "$koniec" +%s) - $(date +%s) ) / 86400 ))
echo "$d: wygasa $koniec ($dni dni)"
[ "$dni" -ge 20 ] || { logger -t cert-wygasa "UWAGA: $d wygasa za $dni dni"; exit 1; }
EOF
chmod +x ~/bin/cert-wygasa.sh
~/bin/cert-wygasa.sh sklep.firma.example
